95	/** Ignored trees (node_modules, build output) scale with the repository, not the change: about 6 s per 90k files. */
96	const IGNORED_LISTING_TIMEOUT_MS = 180_000;
97	const SOURCE_FILE_MAX = 4 * 1024 * 1024;
98	const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
99	const ADDED_FILE_MAX = 16 * 1024 * 1024;
100	const SIGNIFICANT_LINE_MIN = 8;
101	
102	/**
103	 * The content of the protected files present in the workspace (tracked, untracked or ignored), for recognising a new
104	 * file that carries it. A new file is carried when it equals a protected file exactly (whatever its size) or shares a
105	 * significant line with one: a trimmed, non-comment line of at least 8 characters. Files inside `.nexus` take part by
106	 * exact content only (their lines are structural). When the sources cannot all be read within the limits, every new
107	 * file counts as carried: nothing is kept because it could not be compared.
108	 */
109	function protectedContent(root: string, files: string[]): { carriedBy(root: string, relative: string): boolean } {
110	  const hashes = new Set<string>();
111	  const lines = new Set<string>();
112	  let complete = true;
113	  let total = 0;
114	  for (const file of files) {
115	    let size: number;
116	    try {
117	      const st = fs.lstatSync(path.join(root, file));
118	      if (!st.isFile()) continue;
119	      size = st.size;
120	    } catch { continue; }
121	    total += size;
122	    if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
123	    let data: Buffer;
124	    try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
125	    hashes.add(createHash("sha256").update(data).digest("hex"));
126	    if (file.split(/[\\/]/).some((seg) => seg.toLowerCase() === ".nexus")) continue;
127	    for (const line of significantLines(data)) lines.add(line);
128	  }
129	  return {
130	    carriedBy(base: string, relative: string): boolean {
131	      if (!complete) return true;
132	      if (hashes.size === 0 && lines.size === 0) return false;
133	      let data: Buffer;
134	      try {
135	        const st = fs.lstatSync(path.join(base, relative));
136	        if (!st.isFile()) return false;
137	        if (st.size > ADDED_FILE_MAX) return true;
138	        data = fs.readFileSync(path.join(base, relative));
139	      } catch { return true; }
140	      if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
141	      for (const line of significantLines(data)) if (lines.has(line)) return true;
142	      return false;
143	    },
144	  };
