147	function significantLines(data: Buffer): string[] {
148	  return data.toString("latin1").split("\n").map((l) => l.trim())
149	    .filter((l) => l.length >= SIGNIFICANT_LINE_MIN && !l.startsWith("#") && !l.startsWith("//") && /[A-Za-z0-9]/.test(l));
