152	/**
153	 * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
154	 * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
155	 */
156	export function attributesTree(root: string, scratch: string, files: string[]): { tree: string; objects: string } | undefined {
157	  const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
158	    try {
